import type { LegacyRedirectTable } from '../../../src/app/legacyPaths';

/*
 * Server-side copies of the legacy redirect table (src/data/legacy/redirects.json), regenerated by
 * `npm run content:generate` and verified by `npm run content:check`:
 *
 * - vercel.json `redirects`: real permanent redirects on Vercel, before the SPA rewrite.
 * - deploy/legacy-redirects.tsv: the full table for nginx, IIS or a CDN in front of the old host.
 *
 * Vercel limits `redirects` to 2048 entries (schema `maxItems` in @vercel/routing-utils, and
 * https://vercel.com/docs/project-configuration). The per-image `/UploadFile/…` entries are left
 * out of vercel.json to stay far below that: those requests fall through the SPA rewrite, and the
 * in-app resolver sends them to the converted WebP. The old site's `?page=` variants already
 * share one normalized key, and Vercel matches `source` without the query.
 *
 * `source` is compiled by path-to-regexp with case sensitivity on, and the old site's links mixed
 * cases (`/News/Info/N002/4`, `/center/info/CLINICAL/…`). Each source is therefore one unnamed
 * group whose regex spells every letter as `[xX]`, and also accepts the `.html` suffix and the
 * trailing slash the SPA normalizer ignores.
 */

export const VERCEL_REDIRECT_LIMIT = 2048;
/** Our own ceiling, well under Vercel's, so the table can grow without surprises. */
export const VERCEL_REDIRECT_BUDGET = 1000;

const UPLOAD_PREFIX = '/uploadfile/';
/** Characters a normalized, non-upload key may contain. Anything else fails generation. */
const SAFE_KEY = /^\/[a-z0-9._/-]*$/;

export type VercelRedirect = {
  readonly source: string;
  readonly destination: string;
  readonly permanent: true;
  readonly has?: readonly { readonly type: 'query'; readonly key: string; readonly value: string }[];
};

export class VercelRedirectError extends Error {
  readonly name = 'VercelRedirectError';
}

function escapeRegex(text: string): string {
  return text.replace(/[\\^$.*+?()[\]{}|]/g, '\\$&');
}

/** `/news/cate/n006` → `/([Nn][Ee][Ww][Ss]/[Cc][Aa][Tt][Ee]/[Nn]006(?:\.[Hh][Tt][Mm][Ll]?)?/?)`. */
export function caseInsensitiveSource(normalizedPath: string): string {
  if (!SAFE_KEY.test(normalizedPath) || normalizedPath === '/') {
    throw new VercelRedirectError(`Cannot express ${normalizedPath} as a Vercel source`);
  }
  const body = [...normalizedPath.slice(1)]
    .map((char) => (/[a-z]/.test(char) ? `[${char.toUpperCase()}${char}]` : escapeRegex(char)))
    .join('');
  return `/(${body}(?:\\.[Hh][Tt][Mm][Ll]?)?/?)`;
}

function sortedExact(table: LegacyRedirectTable): (readonly [string, string])[] {
  return Object.entries(table.exact).sort(([left], [right]) => (left < right ? -1 : left > right ? 1 : 0));
}

function destinationPath(to: string): string {
  return (to.split('#')[0] ?? '').split('?')[0] ?? '';
}

/** Vercel redirects for the table: query rules first (they share a path with an exact entry). */
export function buildVercelRedirects(table: LegacyRedirectTable): VercelRedirect[] {
  const redirects: VercelRedirect[] = [];
  for (const rule of table.query) {
    redirects.push({
      source: caseInsensitiveSource(rule.path),
      has: [{ type: 'query', key: rule.key, value: `^${escapeRegex(rule.value)}$` }],
      destination: rule.to,
      permanent: true,
    });
  }
  for (const [from, to] of sortedExact(table)) {
    if (from.startsWith(UPLOAD_PREFIX)) continue;
    if (destinationPath(to).toLowerCase() === from) throw new VercelRedirectError(`${from} redirects to itself`);
    redirects.push({ source: caseInsensitiveSource(from), destination: to, permanent: true });
  }
  if (redirects.length > VERCEL_REDIRECT_BUDGET) {
    throw new VercelRedirectError(`${redirects.length} Vercel redirects exceed the budget of ${VERCEL_REDIRECT_BUDGET}`);
  }
  return redirects;
}

/** Top-level members of a JSON object as raw text, so untouched members stay byte-identical. */
function rawMembers(text: string): { readonly key: string; readonly raw: string }[] {
  const parsed: unknown = JSON.parse(text);
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    throw new VercelRedirectError('vercel.json must hold a JSON object');
  }
  const members: { key: string; raw: string }[] = [];
  let depth = 0;
  let index = 0;
  let key: string | undefined;
  let valueStart = -1;
  const finish = (end: number) => {
    if (key !== undefined && valueStart !== -1) members.push({ key, raw: text.slice(valueStart, end).trim() });
    key = undefined;
    valueStart = -1;
  };
  while (index < text.length) {
    const char = text[index]!;
    if (char === '"') {
      const start = index;
      index += 1;
      while (text[index] !== '"') index += text[index] === '\\' ? 2 : 1;
      index += 1;
      if (depth === 1 && key === undefined) {
        key = JSON.parse(text.slice(start, index)) as string;
        while (/\s/.test(text[index] ?? '')) index += 1;
        index += 1; // the colon
        valueStart = index;
      }
      continue;
    }
    if (char === '{' || char === '[') depth += 1;
    else if (char === '}' || char === ']') {
      if (depth === 1) finish(index);
      depth -= 1;
    } else if (char === ',' && depth === 1) finish(index);
    index += 1;
  }
  return members;
}

function renderRedirect(redirect: VercelRedirect): string {
  return `    ${JSON.stringify(redirect)}`;
}

/**
 * vercel.json with `redirects` regenerated in front of every other member, which is kept as
 * written. Vercel applies redirects before the filesystem and rewrites whatever the key order.
 */
export function renderVercelConfig(current: string, table: LegacyRedirectTable): string {
  const others = rawMembers(current).filter((member) => member.key !== 'redirects');
  const redirects = buildVercelRedirects(table).map(renderRedirect).join(',\n');
  const members = [`  "redirects": [\n${redirects}\n  ]`, ...others.map((member) => `  ${JSON.stringify(member.key)}: ${member.raw}`)];
  return `{\n${members.join(',\n')}\n}\n`;
}

/** The whole table, tab-separated, for servers in front of the old host. */
export function renderRedirectTsv(table: LegacyRedirectTable): string {
  const lines = [
    '# Generated by `npm run content:generate` from src/data/legacy/redirects.json; do not edit.',
    '# Old tmuh-education.tmuh.org.tw paths: percent-decoded, lowercase, without `.html` or a trailing',
    '# slash. Match case-insensitively on the decoded path and ignore the old query string, except on',
    '# /other/downloadfile, whose fName rows come first and must be tried before its plain row.',
    '# Targets are paths on the new site root; serve them with the status in the third column.',
    'from\tto\tstatus',
  ];
  for (const rule of table.query) lines.push(`${rule.path}?${rule.key}=${rule.value}\t${rule.to}\t301`);
  for (const [from, to] of sortedExact(table)) {
    if (/[\t\n]/.test(from) || /[\t\n]/.test(to)) throw new VercelRedirectError(`Redirect ${from} cannot be written as TSV`);
    lines.push(`${from}\t${to}\t301`);
  }
  return `${lines.join('\n')}\n`;
}
